    pub fn specific(&self, id: &str) -> bsb::Result<Self> {
        Ok(Self {
            events: self.events.specific(id)?,
        })
    }
    pub fn events(&self) -> &bsb::events::Events {
        &self.events
    }
    pub async fn todo_create(
        &self,
        obs: &bsb::observable::Observable,
        payload: ServiceDemoTodoClientTodoCreateInput,
        timeout: Option<std::time::Duration>,
    ) -> bsb::Result<ServiceDemoTodoClientTodoCreateOutput> {
        let result = self
            .events
            .emit(
                obs,
                "todo.create",
                bsb::serde_json::to_value(payload)?,
                timeout,
            )
            .await?;
        Ok(bsb::serde_json::from_value::<
            ServiceDemoTodoClientTodoCreateOutput,
        >(result)?)
    }
    pub async fn on_todo_created<F, Fut>(&self, handler: F) -> bsb::Result<()>
    where
        F: Fn(bsb::observable::Observable, ServiceDemoTodoClientOnTodoCreatedInput) -> Fut
            + Send
            + Sync
            + 'static,
        Fut: std::future::Future<Output = bsb::Result<()>> + Send + 'static,
    {
        let handler = std::sync::Arc::new(handler);
        self.events
            .listen(
                "todo.created",
                std::sync::Arc::new(move |obs, value| {
                    let handler = handler.clone();
                    Box::pin(async move {
                        let payload = bsb::serde_json::from_value::<
                            ServiceDemoTodoClientOnTodoCreatedInput,
                        >(value)?;
                        let result = handler(obs, payload).await?;
                        Ok(bsb::serde_json::to_value(result)?)
                    })
                }),
            )
            .await
    }
